      "source": "function update(input,previous,event){\n const old=previous||{items:[],nextId:1};const items=old.items.map(x=>({id:x.id,value:x.value}));let nextId=old.nextId;\n if(event.kind==='control'&&event.id==='append'&&items.length<32){items.push({id:nextId,value:nextId});nextId++;}\n if(event.kind==='control'&&event.id==='remove'&&items.length)items.pop();\n if(event.kind==='control'&&event.id==='reset'){items.length=0;nextId=1;}\n const marks=[];items.forEach((item,i)=>{const x=40+(i%8)*76,y=40+Math.floor(i/8)*76;marks.push(sdk.circle({id:'node'+item.id,entityId:'item'+item.id,anchorId:'passage',center:[x,y],radius:24,label:'Item '+item.id+', value '+item.value}));marks.push(sdk.text({id:'label'+item.id,at:[x,y],text:String(item.value),label:'Value '+item.value}));});\n return sdk.frame({title:'Dynamic sequence',description:items.length+' '+(items.length===1?'item.':'items.'),coordinateSpace:{width:Math.max(120,Math.min(8,Math.max(items.length,1))*76),height:Math.max(80,Math.ceil(items.length/8)*76)},marks:marks,controls:[sdk.button({id:'append',label:'Add item',disabled:items.length>=32}),sdk.button({id:'remove',label:'Remove last',disabled:!items.length}),sdk.button({id:'reset',label:'Reset'})],table:{caption:'Every item in current insertion order',columns:['Item ID','Value'],rows:items.map(x=>[x.id,x.value])},state:{items:items,nextId:nextId}});\n}"
